CREATE TABLE employees (
  employee_id  SERIAL PRIMARY KEY,
  last_name    VARCHAR(50) NOT NULL,
  first_name   VARCHAR(50) NOT NULL,
  title        VARCHAR(50),
  birth_date   DATE,
  hire_date    DATE,
  address      VARCHAR(100),
  city         VARCHAR(50),
  region       VARCHAR(50),
  postal_code  VARCHAR(20),
  country      VARCHAR(50),
  notes        TEXT,
  reports_to   INTEGER
);

INSERT INTO employees (employee_id, last_name, first_name, title, birth_date, hire_date, address, city, region, postal_code, country, notes, reports_to) VALUES
  (1, 'Davolio', 'Nancy', 'Sales Representative', '1948-12-08', '1992-05-01', '507 - 20th Ave. E. Apt. 2A', 'Seattle', 'WA', '98122', 'USA', 'Education includes a BA in psychology from Colorado State University. She also completed The Art of the Cold Call. Nancy is a member of Toastmasters International.', 2),
