  (3, 'Leverling', 'Janet', 'Sales Representative', '1963-08-30', '1992-04-01', '722 Moss Bay Blvd.', 'Kirkland', 'WA', '98033', 'USA', 'Janet has a BS degree in chemistry from Boston College. She has also completed a certificate program in food retailing management.', 2),
  (4, 'Peacock', 'Margaret', 'Sales Representative', '1937-09-19', '1993-05-03', '4110 Old Redmond Rd.', 'Redmond', 'WA', '98052', 'USA', 'Margaret holds a BA in English literature from Concordia College and an MA from the American Institute of Culinary Arts.', 2),
  (5, 'Buchanan', 'Steven', 'Sales Manager', '1955-03-04', '1993-10-17', '14 Garrett Hill', 'London', NULL, 'SW1 8JR', 'UK', 'Steven Buchanan graduated from St. Andrews University, Scotland, with a BSC degree. Upon joining the company as a sales representative, he spent 6 months in an orientation program at the Seattle office.', 2),
  (6, 'Suyama', 'Michael', 'Sales Representative', '1963-07-02', '1993-10-17', 'Coventry House Miner Rd.', 'London', NULL, 'EC2 7JR', 'UK', 'Michael is a graduate of Sussex University (MA, economics) and the University of California at Los Angeles (MBA). He has also taken the courses Multi-Cultural Selling and Time Management for the Sales Professional.', 5),
  (7, 'King', 'Robert', 'Sales Representative', '1960-05-29', '1994-01-02', 'Edgeham Hollow Winchester Way', 'London', NULL, 'RG1 9SP', 'UK', 'Robert King served in the Peace Corps and traveled extensively before completing his degree in English at the University of Michigan and then joining the company.', 5),
  (8, 'Callahan', 'Laura', 'Inside Sales Coordinator', '1958-01-09', '1994-03-05', '4726 - 11th Ave. N.E.', 'Seattle', 'WA', '98105', 'USA', 'Laura received a BA in psychology from the University of Washington. She has also completed a course in business French. She reads and translates French.', 2),
  (9, 'Dodsworth', 'Anne', 'Sales Representative', '1966-01-27', '1994-11-15', '7 Houndstooth Rd.', 'London', NULL, 'WG2 7LT', 'UK', 'Anne has a BA degree in English from St. Lawrence College. She is fluent in French and German.', 5);
